<?php
$lang=strtolower((string)($_GET['lang']??$_POST['lang']??'vi'));if(!in_array($lang,['vi','en','zh'],true))$lang='vi';
$tx=[
'vi'=>['title'=>'Cài đặt hệ thống đặt đồ uống','done'=>'Cài đặt hoàn tất.','admin'=>'Vào quản trị trụ sở','front'=>'Xem trang đặt hàng','security'=>'Để an toàn, sau khi cài đặt hãy đổi tên hoặc xóa setup.php trong cPanel.','host'=>'Máy chủ cơ sở dữ liệu','db'=>'Tên cơ sở dữ liệu','user'=>'Tài khoản cơ sở dữ liệu','pass'=>'Mật khẩu cơ sở dữ liệu','url'=>'Địa chỉ website','admin_user'=>'Tài khoản quản trị trụ sở','admin_pass'=>'Mật khẩu quản trị trụ sở','create'=>'Tạo hệ thống','validation'=>'Vui lòng điền thông tin cơ sở dữ liệu; mật khẩu quản trị phải có ít nhất 8 ký tự.','write'=>'Không thể ghi config.local.php. Hãy kiểm tra quyền ghi thư mục.'],
'en'=>['title'=>'Install Ordering System','done'=>'Installation complete.','admin'=>'Open headquarters admin','front'=>'View storefront','security'=>'For security, rename or delete setup.php in cPanel after installation.','host'=>'Database host','db'=>'Database name','user'=>'Database username','pass'=>'Database password','url'=>'Website URL','admin_user'=>'Headquarters admin username','admin_pass'=>'Headquarters admin password','create'=>'Create system','validation'=>'Enter the database details. The admin password must be at least 8 characters.','write'=>'Unable to write config.local.php. Check folder write permissions.'],
'zh'=>['title'=>'點餐系統安裝','done'=>'安裝完成。','admin'=>'進入總部後台','front'=>'查看前台','security'=>'安全起見，安裝完成後可在 cPanel 將 setup.php 改名或刪除。','host'=>'資料庫主機','db'=>'資料庫名稱','user'=>'資料庫帳號','pass'=>'資料庫密碼','url'=>'網站網址','admin_user'=>'總部管理帳號','admin_pass'=>'總部管理密碼','create'=>'建立系統','validation'=>'請填寫資料庫資料，後台密碼至少 8 碼。','write'=>'無法寫入 config.local.php，請確認資料夾可寫入。']];
function sx($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
$done=false;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $host=trim($_POST['db_host']??'localhost');$name=trim($_POST['db_name']??'');$user=trim($_POST['db_user']??'');$pass=$_POST['db_pass']??'';$admin=trim($_POST['admin_user']??'admin');$adminPass=$_POST['admin_pass']??'';$base=rtrim(trim($_POST['base_url']??''),'/');
    try{
        if(!$name||!$user||strlen($adminPass)<8)throw new Exception($tx[$lang]['validation']);
        $pdo=new PDO("mysql:host={$host};dbname={$name};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
        $sql=file_get_contents(__DIR__.'/install.sql');foreach(preg_split('/;\s*(?:\r?\n|$)/',$sql) as $q){if(trim($q))$pdo->exec($q);}
        $hash=password_hash($adminPass,PASSWORD_DEFAULT);$st=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash)');$st->execute([$admin,$hash]);
        $cfg="<?php\ndefine('DB_HOST', ".var_export($host,true).");\ndefine('DB_NAME', ".var_export($name,true).");\ndefine('DB_USER', ".var_export($user,true).");\ndefine('DB_PASS', ".var_export($pass,true).");\ndefine('APP_BASE_URL', ".var_export($base,true).");\ndefine('APP_TIMEZONE', 'Asia/Ho_Chi_Minh');\ndefine('PAYMENT_HOLD_SECONDS', 900);\n";
        if(file_put_contents(__DIR__.'/config.local.php',$cfg)===false)throw new Exception($tx[$lang]['write']);
        if(!is_dir(__DIR__.'/uploads') && !@mkdir(__DIR__.'/uploads',0755,true)) throw new Exception('Unable to create uploads directory.');
        $done=true;
    }catch(Throwable $e){$error=$e->getMessage();}
}
