<h1><?=sx($tx[$lang]['title'])?></h1><?php if($done):?><div class="alert success"><?=sx($tx[$lang]['done'])?></div><p><a class="btn primary block" href="admin/login.php?lang=<?=$lang?>"><?=sx($tx[$lang]['admin'])?></a></p><p><a class="btn block" href="index.php?lang=<?=$lang?>"><?=sx($tx[$lang]['front'])?></a></p><p class="muted"><?=sx($tx[$lang]['security'])?></p><?php else:?><?php if($error):?><div class="alert danger"><?=sx($error)?></div><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="lang" value="<?=sx($lang)?>"><label><?=sx($tx[$lang]['host'])?><input name="db_host" value="localhost" required></label><label><?=sx($tx[$lang]['db'])?><input name="db_name" required></label><label><?=sx($tx[$lang]['user'])?><input name="db_user" required></label><label><?=sx($tx[$lang]['pass'])?><input name="db_pass" type="password"></label><label><?=sx($tx[$lang]['url'])?><input name="base_url" placeholder="https://order.example.com" required></label><label><?=sx($tx[$lang]['admin_user'])?><input name="admin_user" value="admin" required></label><label><?=sx($tx[$lang]['admin_pass'])?><input name="admin_pass" type="password" minlength="8" required></label><button class="btn primary" type="submit"><?=sx($tx[$lang]['create'])?></button></form><?php endif;?></main></body></html>
